// ============================================================================
// CINE_VELOCIDAD — técnicas accionables para el GANCHO ULTRA-VELOCIDAD del magnetar
// Reusa: Magnetar.tsx (partículas GPU), NSLensed.tsx (superficie+beaming), 
//        CinematicCamera.tsx (WeightedRig puro en t). NO reinventar el motor.
// ============================================================================

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 1 — ESTELAS = VELOCIDAD (motion blur por geometría, no post)
//   "el largo de la estela ES la velocidad" (Premiumbeat: más blur = más rápido)
//   En vez de gl_PointSize redondo, dibuja CADA partícula del viento como un
//   SEGMENTO estirado a lo largo de su vector velocidad local v=dpos/dphase.
//   Físico: el viento de pares acelera más allá del cilindro de luz R_LC=cP/2π;
//   la estela se ALARGA con r (más rápido afuera) → la física dicta el largo.
// ─────────────────────────────────────────────────────────────────────────
// Geometría: instancia un quad (2 triángulos) por partícula en lugar de POINTS.
// En el vertex shader, lee la posición ACTUAL (fase ph) y la PREVIA (ph - dph)
// del field-line texture, y orienta el quad a lo largo de (pos - posPrev):
const streakVert = /* glsl */`
uniform sampler2D uFieldData; uniform float uTime, uRotAngle, uTilt, uBeta, uRLC;
attribute float aLineIdx, aPhase, aSpeed;
attribute vec2 aCorner;     // (-1..1, 0..1): x=ancho, y=a lo largo de la estela
varying float vAlpha; varying vec3 vCol; varying float vAlong;
mat3 rotY(float a){float c=cos(a),s=sin(a);return mat3(c,0,s,0,1,0,-s,0,c);}
mat3 rotX(float a){float c=cos(a),s=sin(a);return mat3(1,0,0,0,c,-s,0,s,c);}
vec4 sampleLine(float ph){ return texture2D(uFieldData, vec2(ph,(aLineIdx+0.5)/80.0)); }
void main(){
  float ph  = fract(aPhase + uTime*aSpeed);
  float dph = 0.04 + aSpeed*0.6;            // la estela mira "hacia atrás" en fase
  vec4 fd  = sampleLine(ph);
  vec4 fdP = sampleLine(fract(ph - dph));
  mat3 R = rotY(uRotAngle)*rotX(uTilt);
  vec3 p  = R*fd.xyz;  vec3 pPrev = R*fdP.xyz;
  vec3 vel = p - pPrev;                       // dirección+magnitud de la estela
  float r = fd.w;
  // LARGO RELATIVISTA: crece con r (acelera tras el cilindro de luz) — etiquetable
  float boost = 1.0 + smoothstep(uRLC*0.6, uRLC*2.0, r)*4.0; // tras R_LC se dispara
  vec3 along = vel * boost;
  // ancho perpendicular pequeño (estela fina)
  vec3 view = normalize(cameraPosition - p);
  vec3 side = normalize(cross(normalize(along+1e-5), view)) * 0.015 * (1.0+r*0.02);
  vec3 wp = p + along*aCorner.y + side*aCorner.x;
  vAlong = aCorner.y;
  // color: amber a B bajo → violeta-blanco a B alto (igual que el cuerpo NS)
  vCol = mix(vec3(0.95,0.55,0.18), vec3(0.85,0.6,1.0), uBeta*5.0);
  vAlpha = (1.0 - aCorner.y)*0.5;             // cabeza brillante, cola se apaga
  gl_Position = projectionMatrix*viewMatrix*vec4(wp,1.0);
}`;
// Frag: aditivo, núcleo caliente. (head bright, tail fade = sensación de "pasó")
const streakFrag = /* glsl */`
varying float vAlpha; varying vec3 vCol; varying float vAlong;
void main(){ float a=vAlpha*smoothstep(1.0,0.0,vAlong);
  gl_FragColor=vec4(vCol*(1.0+(1.0-vAlong)*1.5), a); }`;
// NOTA: esto sustituye/duplica StreamingParticles+PairCascade de Magnetar.tsx.
// R_LC en unidades de escena: R_LC = c*P/2π → normaliza al R_STAR=1 del modelo.

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 2 — ABERRACIÓN RELATIVISTA (headlight effect) DEL VIENTO
//   Wikipedia/relativistic beaming: a velocidad↑ los fotones se concentran en
//   un CONO hacia adelante; el lado que se acerca revienta (δ⁴), el que se aleja
//   se apaga y enrojece. YA está hecho en NSLensed para la SUPERFICIE (β=0.18);
//   aquí lo aplicamos al BRILLO de cada estela del viento. MISMA matemática.
// ─────────────────────────────────────────────────────────────────────────
const RELATIVISTIC_BEAMING = /* glsl, añadir al streakVert antes de gl_Position */`
  vec3 vhat = normalize(vel);                 // dir de movimiento de la partícula
  vec3 toCam = normalize(cameraPosition - p);
  float beta = clamp(uBeta + smoothstep(uRLC,uRLC*3.0,r)*0.6, 0.0, 0.95); // acelera
  float gam  = 1.0/sqrt(max(1e-3,1.0-beta*beta));
  float mu   = dot(vhat, toCam);
  float dopp = 1.0/(gam*(1.0 - beta*mu));     // factor Doppler δ
  float beam = pow(clamp(dopp,0.2,4.0), 4.0); // δ⁴ — igual que NSLensed/BHRaytraced
  // blue-shift acercándose, red-shift alejándose
  vec3 dShift = mix(vec3(1.0,0.45,0.3), vec3(0.6,0.78,1.0), clamp((dopp-0.6)/0.8,0.0,1.0));
  vCol *= dShift;  vAlpha *= beam;`;
// EFECTO: el viento que viene HACIA la cámara explota en brillo y azul; el que
// se va se desvanece rojo. Esto SOLO se lee como velocidad si la cámara mira de
// LADO al eje del jet (ver técnica 5). δ⁴ a β=0.18 ≈ ×2 de contraste — real.

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 3 — PARALLAX FORZADO + REFERENCIA DE ESCALA (el "Ranger" de Miller)
//   Interstellar vendió la ola con (a) el Ranger barrido hasta ser un punto y
//   (b) nubes sostenidas ENFRENTE. Aquí: la NS lensada (NSLensed.tsx) es el
//   ancla INMÓVIL y nítida; el viento se desgarra a su alrededor a toda madre.
//   Capas de parallax: 3 profundidades de partículas a velocidades distintas.
// ─────────────────────────────────────────────────────────────────────────
// En MagnetarInner añade 3 instancias del streak-emitter a r distintos:
//   - capa CERCA (r 1.5–3): estelas GRUESAS, rápidas, pasan pegadas a cámara
//   - capa MEDIA (r 3–6): el grueso del viento, beaming máximo
//   - capa LEJOS (r 6–12 + R_LC): estelas finas larguísimas (parallax lento)
// El ojo lee la diferencia de velocidad entre capas como PROFUNDIDAD+VELOCIDAD.
// La NS lensada NO se mueve en pantalla (ancla) → todo lo demás "viaja".
const PARALLAX_LAYERS = [
  { rMin: 1.5, rMax: 3.0,  nStream: 12000, width: 0.03, speedMul: 1.0  }, // foreground rush
  { rMin: 3.0, rMax: 6.0,  nStream: 18000, width: 0.018, speedMul: 0.7 }, // body
  { rMin: 6.0, rMax: 12.0, nStream: 10000, width: 0.010, speedMul: 0.45 },// far, long streaks
];

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 4 — PARTÍCULAS QUE PASAN PEGADAS A CÁMARA (near-camera rush)
//   Premiumbeat: "incluir objetos que pasan muy cerca de la cámara genera más
//   blur → se lee como más rápido". Spawnea un puñado de pares e± SUELTOS (no en
//   línea de campo) que vuelan del eje del jet hacia/junto a la cámara y la
//   cruzan. Estos NO siguen el dipolo: son viento ya escapado tras R_LC (real).
// ─────────────────────────────────────────────────────────────────────────
const FLYBY_PARTICLES = /* glsl spec */`
// 2000 partículas. Cada una: origen en el cono del jet (±Y mag tras tilt),
// velocidad ~0.18c proyectada, vida finita; reaparece (respawn det. por id).
// pos = jetOrigin + dir*(fract(uTime*spd + seed))*range;  estela MUY larga
// cerca de cámara (length(pos-cam)<2 → boost de largo ×3). Aditivo, blanco-azul.
// Etiqueta UI: "viento de pares e± — escapado tras el cilindro de luz".`;

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 5 — CÁMARA: SENTIR EL VIAJE SIN MAREAR (WeightedRig, puro en t)
//   Regla de oro: TRANSLACIÓN con parallax = velocidad sin náusea; ROTACIÓN
//   rápida = náusea. Shutter/blur 180° equivalente (Camera Butter). Reusa
//   addWeight() de CinematicCamera.tsx: shake de BAJA freq (peso, no nervios).
// ─────────────────────────────────────────────────────────────────────────
import { WeightedRig, spherical, lerp3, easeExp, smootherstep, easeInOutCubic } from '@/cinematic/CinematicCamera';
// Programa de cámara del gancho (≈8s): DOLLY-IN lateral al eje del jet.
// Mira de LADO (azimut ~80–100°) para que el beaming del viento se LEA como
// estelas cruzando el cuadro (de frente el headlight colapsa a un punto).
function ganchoVelocidadProgram(t: number) {
  const T = 8.0; const u = Math.min(1, t / T);
  // empuje exponencial hacia adentro: arranca lejos (escala), cae al magnetar
  const r = lerp(22, 6.5, easeExp(u, 3.2));      // "caer" hacia el horizonte
  const az = lerp(1.4, 1.75, smootherstep(u));   // ladea para ver el viento cruzar
  const el = lerp(0.35, 0.08, easeInOutCubic(u));// baja al plano ecuatorial (jet de lado)
  const pos = spherical(az, el, r);
  const target: [number,number,number] = [0, 0, 0]; // la NS = ancla inmóvil
  // FOV se ABRE al final (de 38 a 52) → sensación de aceleración/inminencia
  const fov = lerp(38, 52, easeExp(u, 2.0));
  return { pos, target, fov };
}
// Montaje del Rig — shake de baja frecuencia (peso de grúa) + lag (inercia):
// <WeightedRig programAt={ganchoVelocidadProgram}
//   getT={() => window.__cinematicPulsar.t}   // determinista, render offline
//   posAmp={0.10} targetAmp={0.05}            // un pelín más que default (fuerza)
//   lag={0.55} />                              // arrastre = peso, no marea
// NO autoRotate, NO OrbitControls en el render del gancho (eso es para el lab).

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 6 — SILENCIO → GOLPE (starquake/FRB como beat de impacto)
//   El kick percusivo del starquake YA existe (magnetar-audio). Sincroniza con
//   visual: en t del quake → FLASH global + micro-FREEZE de cámara (0.12s) +
//   un PULSO de aberración (el viento entero se comprime un instante). El golpe
//   tras el silencio multiplica la sensación de fuerza (gramática de impacto).
// ─────────────────────────────────────────────────────────────────────────
const QUAKE_BEAT = /* spec */`
// uQuakeFlash ya existe en Magnetar.tsx. Añade en el program de cámara:
//   if (|t - quakeT| < 0.12) pos = freeze(pos)   // la cámara "encaja el golpe"
// y en streakVert: vAlpha *= 1.0 + uQuakeFlash*2.0; beta += uQuakeFlash*0.15;
// → en el quake TODO el viento revienta y se comprime hacia adelante un frame.`;

// ─────────────────────────────────────────────────────────────────────────
// TÉCNICA 7 — GRADE/POST estilo "la vara" (negros puros, cine)
//   Igual que BHRaytraced/NSLensed: emite HDR LINEAL (linearOutput=true) y deja
//   UN SOLO tonemap ACES en el post compartido (cero doble tonemap). Bloom solo
//   sobre lo que revienta el headlight (luminanceThreshold alto, ~1.2 ya usado).
//   Negros puros: fondo #030408 ya está; el grade DaVinci va en el compositor.
// ─────────────────────────────────────────────────────────────────────────
// Bloom: <Bloom intensity={0.7} luminanceThreshold={1.3} mipmapBlur /> — solo
// los heads de estela con beam>1 cruzan el umbral → estelas con núcleo ardiente.

// ════════════════════════════════════════════════════════════════════
// SPEC FÍSICO ACCIONABLE — VIENTO RELATIVISTA DEL MAGNETAR/PÚLSAR
// Constantes para src/magnetar/Magnetar.tsx (o componente WindOutflow nuevo)
// ════════════════════════════════════════════════════════════════════

// ── Números reales (anclas honestas) ────────────────────────────────
const C_LIGHT = 1.0;                 // c en unidades naturales
const P_FAST  = 2.0e-3;              // s — régimen ms-pulsar para el gancho
const OMEGA   = 2*Math.PI / P_FAST;  // rad/s
// Cilindro de luz: R_LC = cP/2π. En unidades R_STAR (R_NS≈12km):
//   P=2ms -> R_LC ≈ 95 km ≈ 8 R_STAR  (ENTRA EN CUADRO — úsalo)
const R_LC = 8.0;                    // en R_STAR; la "pared de velocidad"
// Co-rotación ecuatorial en superficie: v=2πR/P. Anclar al β del beaming:
const BETA_SURFACE = 0.18;           // = el de NSLensed (doppler δ⁴ consistente)
// Viento más allá de R_LC: factor de Lorentz por régimen (REAL):
const GAMMA_MAGNETAR_FLARE = 20.0;   // Lyubarsky 2006: Γ~10-20  -> v=0.99875c
const GAMMA_PULSAR_WIND    = 1.0e4;  // Cerutti+2020 conservador -> v≈0.999999995c
// (etiqueta en pantalla; para render basta saturar la estela a "c")

// β(γ) honesto:  β = sqrt(1 - 1/γ²)
function betaFromGamma(g){ return Math.sqrt(1.0 - 1.0/(g*g)); }
// γ_FLARE=20 -> β=0.99875 ; γ=1e4 -> β=0.99999999500

// ── Perfil de velocidad del viento v(r): el GRADIENTE = la violencia ──
// Dentro de R_LC: co-rotación rígida v_φ = Ω·s (lineal, crece hacia afuera)
// En R_LC: pared (v_φ -> c, imposible -> líneas se abren)
// Fuera de R_LC: aceleración radial hacia β->1 (acelera "más allá del
//   cilindro de luz" tal cual lo describe el operador)
// GLSL para el vertex shader del viento (ESTELAS = velocidad visible):
const windProfileGLSL = /* glsl */`
  // s = distancia cilíndrica al eje de rotación (después de tilt)
  // r = distancia radial 3D
  uniform float uRLC;        // 8.0
  uniform float uBetaSurf;   // 0.18
  uniform float uGammaWind;  // 20.0 .. 1e4
  uniform float uTime;

  // velocidad co-rotante rígida normalizada a c (clamp en la pared):
  float vCorot(float s){ return min(s / uRLC, 0.999); } // = Ω s / c

  // velocidad del viento radial fuera del cilindro de luz:
  float vWind(float r){
    float betaW = sqrt(1.0 - 1.0/(uGammaWind*uGammaWind)); // ->~1
    // aceleración suave cruzando R_LC (sigmoide): cuasi-quieto -> betaW
    float x = (r - uRLC) / (0.6*uRLC);
    float accel = clamp(x, 0.0, 1.0);
    accel = accel*accel*(3.0-2.0*accel);        // smoothstep
    return mix(uBetaSurf, betaW, accel);
  }

  // LONGITUD DE ESTELA proporcional a la velocidad local (motion blur honesto):
  // mientras más rápido va la partícula, más larga su estela radial.
  float trailLen(float r, float s){
    float v = (r < uRLC) ? vCorot(s) : vWind(r);
    // mapea v∈[0,~1) -> estela [0.05 .. 2.5] R_STAR (no-lineal: revienta cerca de c)
    return 0.05 + 2.45 * pow(v, 3.0);
  }
`;

// ── STRIPED WIND: la falda ondulada ecuatorial (lo más icónico) ──────
// La lámina de corriente oscila en latitud con amplitud = ángulo de tilt.
// Coloca un set EXTRA de partículas concentradas en el ecuador magnético,
// con desplazamiento sinusoidal en θ que se propaga hacia afuera a "c":
const stripedWindGLSL = /* glsl */`
  uniform float uTilt;   // 0.75 rad (≈43°) — ya existe en la escena
  uniform float uTime;
  uniform float uRLC;
  // p = posición radial unitaria; r = radio
  // onda de la current sheet: la latitud del ecuador magnético ondula
  // (retardo de fase = (r - R_LC)/c  -> la onda VIAJA hacia afuera)
  float stripeLatitude(float r, float phi){
    float phase = phi - (r - uRLC) * 6.2831 / uRLC + uTime * 4.0;
    return sin(phase) * uTilt;   // desplazamiento en θ alrededor del ecuador
  }
`;

// ── BUILDER: partículas del viento (CPU) — nuevo componente WindOutflow ─
// Reutiliza el patrón de buildStreamParticles/PairCascade ya existente.
const N_WIND   = 60000;   // viento radial (denso para sensación de chorro)
const N_STRIPE = 25000;   // striped wind ecuatorial (la falda ondulada)
function buildWindParticles(){
  const phi = new Float32Array(N_WIND);
  const cosTh = new Float32Array(N_WIND);  // dirección de salida
  const phase = new Float32Array(N_WIND);  // posición a lo largo del rayo
  const seed = new Float32Array(N_WIND);
  for(let i=0;i<N_WIND;i++){
    phi[i]   = Math.random()*Math.PI*2;
    cosTh[i] = 2*Math.random()-1;          // isótropo (el striped va aparte)
    phase[i] = Math.random();              // recicla 0..1 saliendo radial
    seed[i]  = Math.random();
  }
  return { phi, cosTh, phase, seed };
}
// Striped: concentra cosTh cerca de 0 (ecuador) y aplica stripeLatitude():
function buildStripeParticles(){
  const phi = new Float32Array(N_STRIPE);
  const phase = new Float32Array(N_STRIPE);
  for(let i=0;i<N_STRIPE;i++){
    phi[i]   = Math.random()*Math.PI*2;
    phase[i] = Math.random();
  }
  return { phi, phase };
}

// ── VERTEX: posición + estela del viento (la velocidad SE VE) ─────────
// La estela se renderiza como segmento alargado: en gl.POINTS hazlo con
// gl_PointSize grande + alpha gradiente, o mejor con line-segments /
// stretched billboards. La clave física: estela ∝ vWind(r) (arriba).
const windVert = /* glsl */`
  uniform float uTime; uniform float uRLC; uniform float uBetaSurf;
  uniform float uGammaWind; uniform float uTilt;
  attribute float aPhi; attribute float aCosTh; attribute float aPhase;
  attribute float aSeed;
  varying float vSpeed; varying float vDoppler;
  ${windProfileGLSL}
  mat3 rotX(float a){float c=cos(a),s=sin(a);return mat3(1.,0.,0., 0.,c,-s, 0.,s,c);}
  mat3 rotY(float a){float c=cos(a),s=sin(a);return mat3(c,0.,s, 0.,1.,0., -s,0.,c);}
  void main(){
    // la partícula nace en R_STAR y sale radial; recicla con fract:
    float life = fract(aPhase + uTime * (0.15 + 0.85*aSeed));
    float r = 1.0 + life * 12.0;              // 1 .. 13 R_STAR
    float sinTh = sqrt(max(0.,1.0-aCosTh*aCosTh));
    vec3 dir = vec3(sinTh*cos(aPhi), aCosTh, sinTh*sin(aPhi));
    vec3 p = dir * r;
    p = rotY(uTime*0.3) * rotX(uTilt) * p;     // co-rota + tilt
    // velocidad local -> color/estela
    float s = length(p.xz);                    // distancia cilíndrica
    vSpeed = (r < uRLC) ? vCorot(s) : vWind(r);
    // doppler boost: lado que se acerca brilla (β·n̂ proyectado a cámara)
    vec4 mv = modelViewMatrix * vec4(p,1.0);
    vec3 vn = normalize((modelViewMatrix*vec4(dir,0.0)).xyz);
    float mu = -vn.z;                          // hacia cámara
    float beta = vSpeed;
    vDoppler = pow(1.0/(max(0.01, 1.0 - beta*mu)), 3.0); // δ³ (haz angosto)
    gl_Position = projectionMatrix * mv;
    // estela: punto más grande+alargado donde va más rápido
    gl_PointSize = max(1.0, (1.5 + 4.0*pow(vSpeed,2.0)) * (300.0/-mv.z));
  }`;

const windFrag = /* glsl */`
  varying float vSpeed; varying float vDoppler;
  void main(){
    float d = length(gl_PointCoord-0.5); if(d>0.5) discard;
    // azul-blanco sincrotrón; revienta a blanco con doppler beaming
    vec3 cold = vec3(0.45,0.75,1.0);   // e± frío/lento
    vec3 hot  = vec3(0.95,0.98,1.0);   // relativista, sincrotrón duro
    vec3 col = mix(cold, hot, pow(vSpeed, 0.5));
    float a = smoothstep(0.5,0.05,d) * clamp(vDoppler*0.15, 0.02, 1.0);
    gl_FragColor = vec4(col * (0.6+vDoppler*0.4), a); // additive blend
  }`;

// ── ANILLO DEL CILINDRO DE LUZ (la "pared", referente de escala) ─────
// Un anillo tenue en r=R_LC, ecuatorial, etiquetado "cilindro de luz".
// Igual que las nubes detrás de la ola en Interstellar: da el referente
// FIJO contra el que el viento se ve disparado. Render como ring geometry
// muy sutil (alpha ~0.08) o como banda de partículas estáticas en R_LC.

// ── ETIQUETAS HONESTAS en pantalla (regla del proyecto) ──────────────
//  "viento de pares e⁺e⁻ · γ ~ 20 (giant flare) → v = 0.99875 c"
//  "cilindro de luz R_LC = cP/2π — co-rotación alcanzaría c (imposible)"
//  "striped wind: lámina de corriente ecuatorial (tilt 43°)"
//  "estela ∝ velocidad local · doppler beaming δ³ (lado que se acerca)"

// ─────────────────────────────────────────────────────────────────────
// RelativisticWind.tsx — CAPA 1 (viento radial e± con ESTELAS). 
// Reusa: rotY/rotX del Magnetar, β=0.18 de NSLensed, getTime() determinista.
// Técnica: stretched-billboard instanciado (quad compartido + atributos por
// instancia). El segmento se alinea al vector velocidad en VIEW space y se
// estira proporcional a la velocidad local => estela = velocidad pura.
// ─────────────────────────────────────────────────────────────────────
import { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

const N_WIND   = 45000;      // viento radial (sube/baja según GPU)
const N_JETS   = 8000;       // jets polares
const R_STAR   = 1.0;
const TILT     = 0.75;       // = MAGNETIC_TILT del Magnetar
const BETA     = 0.18;       // = beta de NSLensed (ms-pulsar ecuador)
const R_LC     = 4.5;        // cilindro de luz en unidades de escena (etiqueta evocativa)

// Quad unitario compartido (4 verts, 2 tris). aSide∈{-1,+1} = lado del grosor,
// aEnd∈{0,1} = cabeza(1)/cola(0) de la estela.
function makeWindGeometry() {
  const g = new THREE.InstancedBufferGeometry();
  // x = a lo largo de la estela (0=cola,1=cabeza), y = ancho (-1..1)
  const quad = new Float32Array([0,-1, 1,-1, 1,1, 0,1]);
  g.setAttribute('aQuad', new THREE.Float32BufferAttribute(quad, 2));
  g.setIndex([0,1,2, 0,2,3]);

  const dir   = new Float32Array(N_WIND * 3); // dirección radial de salida (unit)
  const phase = new Float32Array(N_WIND);     // 0..1 desfase de respawn
  const speed = new Float32Array(N_WIND);     // velocidad terminal relativa
  const seed  = new Float32Array(N_WIND);
  for (let i = 0; i < N_WIND; i++) {
    // Distribución: viento isotrópico pero REFORZADO hacia el ecuador
    // (zona del cilindro de luz, donde el viento del púlsar es más denso).
    const u = Math.random() * 2 - 1;
    const eq = Math.sign(u) * Math.pow(Math.abs(u), 1.6); // empuja al ecuador
    const y = eq;
    const rS = Math.sqrt(Math.max(0, 1 - y*y));
    const ph = Math.random() * Math.PI * 2;
    dir[i*3]   = rS * Math.cos(ph);
    dir[i*3+1] = y;
    dir[i*3+2] = rS * Math.sin(ph);
    phase[i] = Math.random();
    speed[i] = 0.7 + Math.random() * 0.3;
    seed[i]  = Math.random();
  }
  const ia = (a:Float32Array,n:number)=>new THREE.InstancedBufferAttribute(a,n);
  g.setAttribute('aDir',   ia(dir,3));
  g.setAttribute('aPhase', ia(phase,1));
  g.setAttribute('aSpeed', ia(speed,1));
  g.setAttribute('aSeed',  ia(seed,1));
  g.instanceCount = N_WIND;
  return g;
}

const windVert = /* glsl */`
precision highp float;
attribute vec2  aQuad;   // x:0=cola..1=cabeza  y:-1..1 ancho
attribute vec3  aDir;    // dirección radial de salida (frame magnético)
attribute float aPhase, aSpeed, aSeed;
uniform float uTime, uRotAngle, uTilt, uBeta, uRLC, uStreakScale, uBIntensity;
uniform float uWidth, uLifeR;        // grosor base; radio de vida (respawn)
varying float vAlong;   // 0=cola..1=cabeza  (gradiente alpha)
varying vec3  vCol;
varying float vBeam;

mat3 rotY(float a){float c=cos(a),s=sin(a);return mat3(c,0,s,0,1,0,-s,0,c);}
mat3 rotX(float a){float c=cos(a),s=sin(a);return mat3(1,0,0,0,c,-s,0,s,c);}

void main(){
  // ── Ciclo de vida: r(t) acelerado. La partícula nace en R_STAR y vuela
  //    radial; respawn por fract => flujo continuo (cero CPU).
  float life = fract(aPhase + uTime * (0.12 + aSpeed*0.10));
  // ACELERACIÓN VIOLENTA, LITERAL: easeExp (cuadrático+). Lejos = más rápido.
  float accel = life*life*(3.0-2.0*life);        // smootherstep-ish ramp
  float r = mix(R_STAR*1.02, uLifeR, accel);

  // velocidad local (derivada de r) -> longitud de la estela = velocidad pura
  float vLocal = (uLifeR - R_STAR) * (2.0*life - life*life*0.0); // ~ d(accel)/dt
  vLocal = clamp(vLocal * aSpeed, 0.0, 1.0);
  float streakLen = (0.15 + vLocal * uStreakScale);  // ESTELA crece con v

  // Punto base (cabeza) en el frame magnético, luego al frame mundo (rot+tilt)
  vec3 dirM = normalize(aDir);
  vec3 head = dirM * r;
  // La estela se extiende HACIA ATRÁS sobre la trayectoria radial
  vec3 tail = dirM * (r - streakLen);
  mat3 M = rotY(uRotAngle) * rotX(uTilt);
  vec3 pHeadW = M * head;
  vec3 pTailW = M * tail;
  vec3 segW   = M * dirM;   // dirección de la estela en mundo

  // Posición a lo largo del segmento (cabeza..cola)
  vec3 worldPos = mix(pTailW, pHeadW, aQuad.x);
  vLong = aQuad.x;

  // ── Estirado en VIEW space: alinear el ancho perpendicular al segmento
  //    proyectado en pantalla (stretched billboard, NVIDIA GDC2003).
  vec4 mvHead = modelViewMatrix * vec4(pHeadW,1.0);
  vec4 mvTail = modelViewMatrix * vec4(pTailW,1.0);
  vec4 mvPos  = mix(mvTail, mvHead, aQuad.x);
  vec2 segView = normalize((mvHead.xy/mvHead.w) - (mvTail.xy/mvTail.w) + 1e-5);
  vec2 perp    = vec2(-segView.y, segView.x);
  // grosor adelgaza hacia la cola (estela cónica = motion blur)
  float w = uWidth * mix(0.35, 1.0, aQuad.x);
  mvPos.xy += perp * aQuad.y * w;

  gl_Position = projectionMatrix * mvPos;

  // ── DOPPLER BEAMING (δ⁴) real, como NSLensed: cabeza que se acerca revienta.
  vec3 viewDir = normalize(-(modelViewMatrix * vec4(worldPos,1.0)).xyz);
  vec3 velDir  = normalize((modelViewMatrix * vec4(segW,0.0)).xyz);
  float beta   = uBeta * (0.6 + 0.4*vLocal);   // más β conforme acelera
  float g      = 1.0/sqrt(max(1e-3,1.0-beta*beta));
  float dopp   = 1.0/(g*(1.0 - dot(velDir*beta, viewDir)));
  vBeam = pow(clamp(dopp,0.25,3.0), 4.0);

  // Color: pair-cascade blanco-azul (acercándose) -> rojo (alejándose),
  // misma paleta que el cuerpo NS a B alto.
  vec3 cBlue = vec3(0.72,0.82,1.0);
  vec3 cRed  = vec3(1.0,0.42,0.30);
  vCol = mix(cRed, cBlue, clamp((dopp-0.65)/0.7,0.0,1.0));
}
`;

const windFrag = /* glsl */`
precision highp float;
varying float vLong;  varying vec3 vCol;  varying float vBeam;
void main(){
  // gradiente cabeza->cola = motion blur (cabeza brillante, cola se apaga)
  float a = pow(vLong, 1.8);          // cabeza=1, cola=0
  // núcleo brillante + halo: HDR para que el Bloom reviente la cabeza
  vec3 col = vCol * (0.6 + 2.4*vBeam) * (0.4 + a);
  gl_FragColor = vec4(col, a);
}
`;

export function RelativisticWind({ getTime, bIntensity=1, streakScale=2.2 }:{
  getTime:()=>number; bIntensity?:number; streakScale?:number;
}) {
  const geo = useMemo(makeWindGeometry, []);
  const u = useMemo(()=>({
    uTime:{value:0}, uRotAngle:{value:0}, uTilt:{value:TILT}, uBeta:{value:BETA},
    uRLC:{value:R_LC}, uStreakScale:{value:streakScale}, uBIntensity:{value:bIntensity},
    uWidth:{value:0.012}, uLifeR:{value:16.0},
  }),[]);
  useFrame(()=>{
    const t = getTime();
    u.uTime.value = t;
    u.uRotAngle.value = (Math.PI*2/6.0) * t; // P=6s, igual que Magnetar
    u.uStreakScale.value = streakScale;
    u.uBIntensity.value = bIntensity;
  });
  return (
    <mesh frustumCulled={false}>
      <primitive object={geo} attach="geometry" />
      <shaderMaterial vertexShader={windVert} fragmentShader={windFrag}
        uniforms={u} transparent depthWrite={false}
        blending={THREE.AdditiveBlending} toneMapped={false}/>
    </mesh>
  );
}

